<?php
require_once __DIR__.'/config/auth.php'; require_role('admin','teacher');$me=current_user();$id=(int)($_GET['id']??0);
$sql="SELECT s.group_id,s.lesson_title FROM class_sessions s WHERE s.id=?";$a=[$id];if($me['role']==='teacher'){$sql.=' AND s.teacher_id=?';$a[]=$me['id'];}$st=$pdo->prepare($sql);$st->execute($a);$session=$st->fetch();if(!$session){http_response_code(404);exit('Дарс ёфт нашуд');}
$st=$pdo->prepare("SELECT u.full_name,u.student_code,a.scanned_at,a.status,a.source,a.note FROM users u LEFT JOIN attendance a ON a.student_id=u.id AND a.class_session_id=? WHERE u.role='student' AND u.group_id=? ORDER BY u.full_name");$st->execute([$id,$session['group_id']]);
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename=class_'.$id.'_attendance.csv');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');$csvSafe=static function($v){$v=(string)($v??'');return preg_match('/^[=+@\-\t\r]/u',$v)?"'".$v:$v;};fputcsv($o,['Ному насаб','Рамзи донишҷӯ','Ҳолат','Вақт','Манбаъ','Шарҳ'],';');while($r=$st->fetch())fputcsv($o,array_map($csvSafe,[$r['full_name'],$r['student_code'],$r['scanned_at']?($r['status']==='late'?'Дер омад':($r['status']==='excused'?'Узрнок':'Ҳозир')):'Ғоиб',$r['scanned_at']??'',($r['source']??'')==='manual'?'Дастӣ':'QR',$r['note']??'']),';');fclose($o);exit;
